<section><h1>Pending registrations</h1><div class="table-wrap"><table><thead><tr><th>Applicant</th><th>Username</th><th>Requested role</th><th>Review</th></tr></thead><tbody><?php foreach (($result['items'] ?? array()) as $request): ?><tr><td><?= dts_escape(trim($request['firstname'].' '.$request['lastname'])) ?></td><td><?= dts_escape($request['username']) ?></td><td><?= dts_escape($request['requested_role_name']) ?></td><td><form method="post" action="<?= dts_escape(site_url('registrations/review/'.$request['registration_id'])) ?>"><select name="status"><option value="APPROVED">Approve</option><option value="REJECTED">Reject</option></select><select name="assigned_role_id"><option value="">No role (for rejection)</option><?php foreach ($roles as $role): ?><option value="<?= dts_escape($role['role_id']) ?>"><?= dts_escape($role['role_name']) ?></option><?php endforeach; ?></select><input name="review_remarks" placeholder="Remarks"><button type="submit">Submit</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
